  t[", resto "] = ", remainder ";
  t[",\\ s \\leftarrow 0 \\\\ &\\textbf{mientras } x > 0: \\\\ &\\quad s \\leftarrow s + (x \\bmod 10) \\\\ &\\quad x \\leftarrow \\lfloor x / 10 \\rfloor \\\\ &\\textbf{devolver } s \\end{aligned}"] = ",\\ s \\leftarrow 0 \\\\ &\\textbf{while } x > 0: \\\\ &\\quad s \\leftarrow s + (x \\bmod 10) \\\\ &\\quad x \\leftarrow \\lfloor x / 10 \\rfloor \\\\ &\\textbf{return } s \\end{aligned}";
  t[". Con 100 números nunca hacen falta más de 7, porque $2^7 = 128 \\ge 100$."] = ". With 100 numbers you never need more than 7, because $2^7 = 128 \\ge 100$.";
  t[".º</strong>: caen las primeras y ahí se para. Por eso el paso tiene que valer para <strong>todo</strong> $k$, no solo para unos cuantos."] = "</strong>: the first ones fall and there it stops. That is why the step has to hold for <strong>every</strong> $k$, not just for a few.";
  t["0{,}000\\,000\\,000\\,53\\ \\text{m} = 5{,}3\\cdot 10^{-10}"] = "0{.}000\\,000\\,000\\,53\\ \\text{m} = 5{.}3\\cdot 10^{-10}";
  t["0{,}\\overline{6}"] = "0{.}\\overline{6}";
  t["1 000 € al 5 % durante 2 años: simple, 1 100 €; compuesto, $1000\\cdot 1{,}05^2 = 1\\,102{,}5$ €. Los intereses del primer año también producen intereses."] = "1,000 € at 5 % for 2 years: simple, 1,100 €; compound, $1000\\cdot 1{.}05^2 = 1\\,102{.}5$ €. The first year's interest also earns interest.";
  t["1 999 a las centenas: truncado, 1 900; redondeado, 2 000. Truncar siempre baja; redondear va al más cercano."] = "1,999 to the hundreds: truncated, 1,900; rounded, 2,000. Truncating always goes down; rounding goes to the nearest.";
  t["1 m son 100 cm, pero 1 m² son $100^2 = 10\\,000$ cm². El factor se eleva al cuadrado, y al cubo para volúmenes."] = "1 m is 100 cm, but 1 m² is $100^2 = 10\\,000$ cm². The factor is squared, and cubed for volumes.";
