  t["3{,}47 = 3 + \\frac{4}{10} + \\frac{7}{100}"] = "3{.}47 = 3 + \\frac{4}{10} + \\frac{7}{100}";
  t["60 es el primer número que es múltiplo de 12 y de 20 a la vez: el primero destella en el 12, 24, 36, 48, 60 y el segundo en el 20, 40, 60."] = "60 is the first number that is a multiple of both 12 and 20: the first flashes at 12, 24, 36, 48, 60 and the second at 20, 40, 60.";
  t[": \\\\ &\\quad s \\leftarrow 2s + (i \\bmod 2) \\\\ &\\textbf{devolver } s \\end{aligned}"] = ": \\\\ &\\quad s \\leftarrow 2s + (i \\bmod 2) \\\\ &\\textbf{return } s \\end{aligned}";
