  t["De Morgan vale igual aquí: $\\overline{A\\cap B} = \\overline{A}\\cup\\overline{B}$."] = "De Morgan works here just the same: $\\overline{A\\cap B} = \\overline{A}\\cup\\overline{B}$.";
  t["De Morgan: al negar una «y» sale una «o». Con un solo suspenso la frase original ya es falsa."] = "De Morgan: negating an “and” gives an “or”. A single fail already makes the original sentence false.";
