  t["Lo que está en A quitando lo que comparte con B."] = "What is in A, taking away what it shares with B.";
  t["Lo que se conserva es el producto velocidad × tiempo, que es la distancia: 240 km. A 120 km/h tardaría 2 horas."] = "What is conserved is the product speed × time, which is the distance: 240 km. At 120 km/h it would take 2 hours.";
  t["Lo que significa realmente un exponente"] = "What an exponent really means";
