  t["Localizar la cifra de las centenas: en $47\\,\\underline{3}62$ es el 3. Todo lo que está a su derecha, el 62, va a desaparecer."] = "Locate the hundreds digit: in $47{,}\\underline{3}62$ it is the 3. Everything to its right, the 62, is going to disappear.";
  t["Localizar números en la recta"] = "Locating numbers on the line";
  t["Longitud"] = "Length";
