  t["¡Es ese!"] = "That's it!";
  t["«$x + 1 = 3$» no es una proposición: depende de $x$. Se llama <em>predicado</em>, y se convierte en proposición cuantificándolo, es decir, diciendo <strong>de cuántos</strong> objetos se afirma."] = "“$x + 1 = 3$” is not a proposition: it depends on $x$. It is called a <em>predicate</em>, and it turns into a proposition when you quantify it, that is, when you say <strong>how many</strong> objects it is being claimed of.";
  t["«$x + 1 = 3$» — depende de $x$"] = "“$x + 1 = 3$” — it depends on $x$";
  t["«2 + 2 = 5» (falsa)"] = "“2 + 2 = 5” (false)";
